import pytest
from candidate import decimal_to_binary

class TestDecimalToBinary(unittest.TestCase):
    def test_decimal_to_binary_15(self):
        self.assertEqual(decimal_to_binary(15), "db1111db")

    def test_decimal_to_binary_32(self):
        self.assertEqual(decimal_to_binary(32), "db100000db")

    def test_decimal_to_binary_zero(self):
        self.assertEqual(decimal_to_binary(0), "db0db")

    def test_decimal_to_binary_one(self):
        self.assertEqual(decimal_to_binary(1), "db1db")

    def test_decimal_to_binary_two(self):
        self.assertEqual(decimal_to_binary(2), "db10db")

    def test_decimal_to_binary_three(self):
        self.assertEqual(decimal_to_binary(3), "db11db")

    def test_decimal_to_binary_seven(self):
        self.assertEqual(decimal_to_binary(7), "db111db")

    def test_decimal_to_binary_ten(self):
        self.assertEqual(decimal_to_binary(10), "db1010db")

    def test_decimal_to_binary_one_hundred(self):
        self.assertEqual(decimal_to_binary(100), "db1100100db")

    def test_decimal_to_binary_255(self):
        self.assertEqual(decimal_to_binary(255), "db11111111db")

    def test_decimal_to_binary_1024(self):
        self.assertEqual(decimal_to_binary(1024), "db10000000000db")

    def test_decimal_to_binary_large_number(self):
        self.assertEqual(decimal_to_binary(2**20), "db" + "1" + "0" * 20 + "db")

    def test_decimal_to_binary_return_type_is_string(self):
        self.assertIsInstance(decimal_to_binary(15), str)

    def test_decimal_to_binary_starts_with_db(self):
        self.assertTrue(decimal_to_binary(42).startswith("db"))

    def test_decimal_to_binary_ends_with_db(self):
        self.assertTrue(decimal_to_binary(42).endswith("db"))

    def test_decimal_to_binary_inner_is_binary_digits(self):
        result = decimal_to_binary(123)
        inner = result[2:-2]
        for ch in inner:
            self.assertIn(ch, "01")

    def test_decimal_to_binary_negative_number(self):
        with self.assertRaises((ValueError, TypeError, ArithmeticError)):
            decimal_to_binary(-5)

    def test_decimal_to_binary_none_raises_error(self):
        with self.assertRaises(TypeError):
            decimal_to_binary(None)

    def test_decimal_to_binary_string_raises_error(self):
        with self.assertRaises(TypeError):
            decimal_to_binary("15")

    def test_decimal_to_binary_float_raises_error(self):
        with self.assertRaises(TypeError):
            decimal_to_binary(2.5)

    def test_decimal_to_binary_list_raises_error(self):
        with self.assertRaises(TypeError):
            decimal_to_binary([1, 2, 3])

    def test_decimal_to_binary_bool_true(self):
        self.assertEqual(decimal_to_binary(True), "db1db")

    def test_decimal_to_binary_bool_false(self):
        self.assertEqual(decimal_to_binary(False), "db0db")

    def test_decimal_to_binary_no_leading_zeros_in_binary(self):
        result = decimal_to_binary(8)
        self.assertEqual(result, "db1000db")

    def test_decimal_to_binary_power_of_two(self):
        self.assertEqual(decimal_to_binary(4), "db100db")

    def test_decimal_to_binary_very_small_positive(self):
        self.assertEqual(decimal_to_binary(1), "db1db")

    def test_decimal_to_binary_very_large(self):
        val = 2**100
        expected = "db" + bin(val)[2:] + "db"
        self.assertEqual(decimal_to_binary(val), expected)

if __name__ == '__main__':
    unittest.main()
